// Content with portions generated by generative AI platform
package org.eclipse.kura.web.shared;

/**
 * Encodes the file upload errors that the FileServlet reports in the response body, so that the UI can recognize them.
 */
public final class FileUploadErrors {

    private static final String SIZE_LIMIT_EXCEEDED_PREFIX = "UPLOAD_SIZE_LIMIT_EXCEEDED:";
    private static final String UPLOAD_ALREADY_IN_PROGRESS = "UPLOAD_ALREADY_IN_PROGRESS";

    private FileUploadErrors() {
    }

    public static String sizeLimitExceeded(long maxSizeBytes) {
        return SIZE_LIMIT_EXCEEDED_PREFIX + maxSizeBytes;
    }

    public static String uploadAlreadyInProgress() {
        return UPLOAD_ALREADY_IN_PROGRESS;
    }

    /**
     * Returns true if the response reports that the upload was rejected because another upload is in progress.
     */
    public static boolean isUploadAlreadyInProgress(String response) {
        return response != null && response.contains(UPLOAD_ALREADY_IN_PROGRESS);
    }

    /**
     * Returns the maximum upload size reported in the response, or -1 if the response is not a size limit error.
     */
    public static long parseSizeLimitExceeded(String response) {
        if (response == null) {
            return -1;
        }

        int start = response.indexOf(SIZE_LIMIT_EXCEEDED_PREFIX);
        if (start == -1) {
            return -1;
        }

        start += SIZE_LIMIT_EXCEEDED_PREFIX.length();
        int end = start;
        while (end < response.length() && Character.isDigit(response.charAt(end))) {
            end++;
        }

        if (end == start) {
            return -1;
        }

        try {
            return Long.parseLong(response.substring(start, end));
        } catch (NumberFormatException e) {
            return -1;
        }
    }
}
